"""The circom `_structure.json` (--print_tree_info) of an r1cs generated by
`llzk-translate --llzk-to-r1cs`, rebuilt from the .llzk it was generated from.

llzk-translate evaluates the constrain function of main, inlining the constrain
function of every subcomponent where it is called, so the constraints of the
r1cs come out in that execution order. Interpreting the @constrain functions of
the .llzk (parsed with llzk2core's LLZKParser) in that same order says which
component instance emits each constraint; the .llzk-layout says which wire is
which signal of which instance. Both are checked against the .r1cs itself.
"""

import json
import re
import sys
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple

from llzk_r1cs import parse_r1cs

from execution.main_execution import init_llzk_parser
from llzk_dialects.core_utils import FIELD_PRIMES


class LLZKStructureError(Exception):
    pass


# ── Values of the interpreter ────────────────────────────────────────────────

@dataclass(frozen=True)
class Ref:
    """Storage of the circuit: a component instance, a signal or an aggregate
    of them, as a path from main. Paths are in circom terms: `x$inputs` is
    folded into `x` and `idx_N` is N, so `main["c$inputs"][0]["in"][1]` and
    `main["c"][0]["in"][1]` are both ('c', 0, 'in', 1)."""
    path: Tuple


@dataclass(frozen=True)
class Unknown:
    """A value depending on signals (or nondeterministic): only the signals
    it depends on are tracked."""
    signals: frozenset = frozenset()


@dataclass
class Array:
    dims: Tuple[int, ...]
    data: Dict[Tuple[int, ...], object] = field(default_factory=dict)

    def read(self, idx):
        if len(idx) < len(self.dims):
            sub = Array(self.dims[len(idx):])
            for k, v in self.data.items():
                if k[:len(idx)] == idx:
                    sub.data[k[len(idx):]] = v
            return sub
        return self.data.get(idx, Unknown())

    def write(self, idx, value):
        if isinstance(value, Array):
            for k, v in value.data.items():
                self.data[idx + k] = v
        else:
            self.data[idx] = value


class Return(Exception):
    def __init__(self, values):
        self.values = values


def _dims(type_str: str) -> Tuple[int, ...]:
    m = re.search(r"<\s*([\d,\s]+?)\s+x\s", type_str)
    return tuple(int(d) for d in m.group(1).split(",")) if m else ()


def _signals(value) -> frozenset:
    if isinstance(value, Ref):
        return frozenset([value.path])
    if isinstance(value, Unknown):
        return value.signals
    if isinstance(value, Array):
        return frozenset().union(*(_signals(v) for v in value.data.values()))
    return frozenset()


def _name(sym) -> str:
    return str(sym).lstrip("@")


# ── Interpreter of the @constrain functions ─────────────────────────────────

@dataclass
class Instance:
    path: Tuple
    struct: str
    parent: Optional[Tuple]
    children: List[Tuple] = field(default_factory=list)


class ConstrainInterpreter:

    def __init__(self, module, prime: int):
        self.prime = prime
        self.structs = {}    # "T::T" -> StructDef
        self.functions = {}  # "F::F" / "T::T::constrain" -> FunctionDef
        self.globals = {}    # "global::g" -> value
        self._index(module.body, [])
        main = re.search(r"@([\w$]+)::@([\w$]+)", str(module.main_type))
        self.main_struct = f"{main.group(1)}::{main.group(2)}"
        self.instances: Dict[Tuple, Instance] = {}
        self.constraints: List[Tuple[Tuple, frozenset]] = []
        self.stack: List[Tuple] = []

    def _index(self, ops, scope):
        for op in ops:
            kind = type(op).__name__
            if kind in ("PolyTemplate", "NestedModuleOp", "StructDef"):
                inner = scope + [_name(op.sym_name)]
                if kind == "StructDef":
                    self.structs["::".join(inner)] = op
                self._index(op.body, inner)
            elif kind == "FunctionDef":
                self.functions["::".join(scope + [_name(op.sym_name)])] = op
            elif kind == "GlobalDef":
                self.globals["::".join(scope + [_name(op.sym_name)])] = self._global_value(op)

    def _global_value(self, op):
        init = str(op.initial_value)
        values = [int(v) for v in re.findall(r"(-?\d+)\s*:", init)]
        dims = _dims(str(op.type_))
        if not dims:
            return values[0] if values else Unknown()
        arr = Array(dims)
        for flat, v in enumerate(values):
            idx, rest = [], flat
            for d in reversed(dims):
                idx.append(rest % d)
                rest //= d
            arr.data[tuple(reversed(idx))] = v % self.prime
        return arr

    # Circom compares field elements as signed values in (-p/2, p/2].
    def _signed(self, v):
        return v - self.prime if v > self.prime // 2 else v

    def run(self):
        constrain = self.functions[self.main_struct + "::constrain"]
        args = [Ref(())] + [Ref((name,)) for name in self._arg_names(constrain)]
        self._enter_instance((), self.main_struct, None)
        self.stack.append(())
        self._call(constrain, args)
        self.stack.pop()

    def _arg_names(self, function) -> List[str]:
        # Without the self argument of @constrain
        return [name for _, name in _signature_args(function)[1:]]

    def _enter_instance(self, path, struct, parent):
        if path in self.instances:
            raise LLZKStructureError(f"the constrain function of {path} is called twice")
        self.instances[path] = Instance(path, struct, parent)
        if parent is not None:
            self.instances[parent].children.append(path)

    def _call(self, function, args):
        env = {}
        for (arg, _), value in zip(_signature_args(function), args):
            env[arg] = value
        try:
            self._block(function.body, env)
        except Return as r:
            return r.values
        return []

    def _block(self, ops, env):
        """Run ops; the operands of a terminating scf.yield/scf.condition are returned."""
        for op in ops:
            kind = type(op).__name__
            handler = getattr(self, "_op_" + kind, None)
            if handler is None:
                raise LLZKStructureError(f"unsupported operation {kind}: {op!r}")
            result = handler(op, env)
            if kind in ("SCFYield", "SCFCondition"):
                return result
        return None

    def _get(self, env, var):
        name = var.name if hasattr(var, "name") else str(var)
        if name not in env:
            raise LLZKStructureError(f"undefined SSA value {name}")
        return env[name]

    def _set(self, env, var, value):
        env[var.name if hasattr(var, "name") else str(var)] = value

    def _set_results(self, env, results, values):
        flat = _result_names(results)
        if len(values) != len(flat):
            raise LLZKStructureError(f"{len(values)} values for the results {flat}")
        for name, value in zip(flat, values):
            env[name] = value

    # ── Constants, casts and arithmetic ──

    def _op_FeltConst(self, op, env):
        self._set(env, op.result, int(op.constant) % self.prime)

    def _op_ArithConst(self, op, env):
        value = str(op.value).strip("'")
        self._set(env, op.result, 1 if value == "true" else 0 if value == "false" else int(value))

    def _unary(self, op, env, operand, fn):
        v = self._get(env, operand)
        self._set(env, op.result, fn(v) if isinstance(v, int) else Unknown(_signals(v)))

    def _op_CastToIndex(self, op, env):
        self._unary(op, env, op.value, lambda v: v)

    def _op_CastToFelt(self, op, env):
        self._unary(op, env, op.value, lambda v: v % self.prime)

    def _op_ArithCast(self, op, env):
        self._unary(op, env, op.operand, lambda v: v)

    def _op_FeltUnary(self, op, env):
        p = self.prime
        fns = {"felt.neg": lambda v: (-v) % p,
               "felt.inv": lambda v: pow(v, -1, p) if v else 0,
               "felt.bit_not": lambda v: (~v) % p}
        self._unary(op, env, op.operand, fns[str(op._op).strip("'")])

    def _op_BoolNot(self, op, env):
        self._unary(op, env, op.operand, lambda v: 1 - v)

    def _binary(self, op, env, fn):
        a, b = self._get(env, op.lhs), self._get(env, op.rhs)
        if isinstance(a, int) and isinstance(b, int):
            self._set(env, op.result, fn(a, b))
        else:
            self._set(env, op.result, Unknown(_signals(a) | _signals(b)))

    def _op_FeltBinary(self, op, env):
        p, s = self.prime, self._signed
        fns = {
            "felt.add": lambda a, b: (a + b) % p,
            "felt.sub": lambda a, b: (a - b) % p,
            "felt.mul": lambda a, b: (a * b) % p,
            "felt.div": lambda a, b: a * pow(b, -1, p) % p if b else 0,
            "felt.pow": lambda a, b: pow(a, b, p),
            "felt.uintdiv": lambda a, b: a // b if b else 0,
            "felt.umod": lambda a, b: a % b if b else 0,
            "felt.sintdiv": lambda a, b: int(s(a) / s(b)) % p if b else 0,
            "felt.smod": lambda a, b: (s(a) - s(b) * int(s(a) / s(b))) % p if b else 0,
            "felt.shl": lambda a, b: (a << b) % p,
            "felt.shr": lambda a, b: a >> b,
            "felt.bit_and": lambda a, b: a & b,
            "felt.bit_or": lambda a, b: a | b,
            "felt.bit_xor": lambda a, b: a ^ b,
        }
        self._binary(op, env, fns[str(op._op).strip("'")])

    def _op_ArithBinary(self, op, env):
        fns = {
            "arith.addi": lambda a, b: a + b, "arith.subi": lambda a, b: a - b,
            "arith.muli": lambda a, b: a * b,
            "arith.divsi": lambda a, b: int(a / b), "arith.divui": lambda a, b: a // b,
            "arith.remsi": lambda a, b: a - b * int(a / b), "arith.remui": lambda a, b: a % b,
            "arith.andi": lambda a, b: a & b, "arith.ori": lambda a, b: a | b,
            "arith.xori": lambda a, b: a ^ b, "arith.shli": lambda a, b: a << b,
            "arith.shrsi": lambda a, b: a >> b, "arith.shrui": lambda a, b: a >> b,
            "arith.maxsi": max, "arith.maxui": max, "arith.minsi": min, "arith.minui": min,
        }
        self._binary(op, env, fns[str(op._op).strip("'")])

    _CMP = {"eq": lambda a, b: a == b, "ne": lambda a, b: a != b,
            "lt": lambda a, b: a < b, "le": lambda a, b: a <= b,
            "gt": lambda a, b: a > b, "ge": lambda a, b: a >= b}

    def _op_ArithCmpi(self, op, env):
        pred = str(op.predicate).strip("'").lstrip("su") if str(op.predicate).strip("'") not in ("eq", "ne") \
            else str(op.predicate).strip("'")
        self._binary(op, env, lambda a, b: int(self._CMP[pred](a, b)))

    def _op_BoolCmp(self, op, env):
        pred = str(op.predicate).strip("'")
        felt = any("felt" in str(t) for t in op.types)
        conv = self._signed if felt else (lambda v: v)
        self._binary(op, env, lambda a, b: int(self._CMP[pred](conv(a), conv(b))))

    def _op_BoolBinary(self, op, env):
        fns = {"bool.and": lambda a, b: a & b, "bool.or": lambda a, b: a | b,
               "bool.xor": lambda a, b: a ^ b}
        self._binary(op, env, fns[str(op._op).strip("'")])

    def _op_BoolAssert(self, op, env):
        pass

    def _op_LLZKNondet(self, op, env):
        dims = _dims(str(op.result_type))
        self._set(env, op.result, Array(dims) if dims else Unknown())

    def _op_GlobalRead(self, op, env):
        value = self.globals[str(op.name_ref).lstrip("@").replace("::@", "::")]
        self._set(env, op.result, Array(value.dims, dict(value.data)) if isinstance(value, Array) else value)

    # ── Aggregates and storage ──

    def _member(self, struct_ref: Ref, member: str) -> Ref:
        # llzk2core reads `@x$inputs` as `@x_inputs`
        for suffix in ("$inputs", "_inputs"):
            if member.endswith(suffix):
                return Ref(struct_ref.path + (member[:-len(suffix)],))
        return Ref(struct_ref.path + (member,))

    def _op_StructReadm(self, op, env):
        comp = self._get(env, op.component)
        if not isinstance(comp, Ref):
            raise LLZKStructureError(f"struct.readm on a non-storage value: {op!r}")
        self._set(env, op.result, self._member(comp, _name(op.member_name)))

    def _op_StructWritem(self, op, env):
        pass

    def _op_StructNew(self, op, env):
        self._set(env, op.result, Unknown())

    def _indices(self, op, env):
        idx = tuple(self._get(env, i) for i in op.indices)
        if not all(isinstance(i, int) for i in idx):
            raise LLZKStructureError(f"array index depends on a signal: {op!r}")
        return idx

    def _op_ArrayRead(self, op, env):
        arr, idx = self._get(env, op.arr_ref), self._indices(op, env)
        if isinstance(arr, Ref):
            self._set(env, op.result, Ref(arr.path + idx))
        elif isinstance(arr, Array):
            self._set(env, op.result, arr.read(idx))
        else:
            self._set(env, op.result, Unknown(_signals(arr)))

    _op_ArrayExtract = _op_ArrayRead

    def _op_ArrayWrite(self, op, env):
        arr = self._get(env, op.arr_ref)
        if isinstance(arr, Array):
            arr.write(self._indices(op, env), self._get(env, op.rvalue))

    _op_ArrayInsert = _op_ArrayWrite

    def _op_ArrayNew(self, op, env):
        arr = Array(_dims(str(op.result_type)))
        for flat, e in enumerate(op.elements):
            idx, rest = [], flat
            for d in reversed(arr.dims):
                idx.append(rest % d)
                rest //= d
            arr.data[tuple(reversed(idx))] = self._get(env, e)
        self._set(env, op.result, arr)

    def _op_ArrayLen(self, op, env):
        arr, dim = self._get(env, op.arr_ref), self._get(env, op.dim)
        dims = arr.dims if isinstance(arr, Array) else _dims(str(op.arr_type))
        self._set(env, op.result, dims[dim] if isinstance(dim, int) and dim < len(dims) else Unknown())

    def _op_PodNew(self, op, env):
        self._set(env, op.result, {_name(k): self._get(env, v) for k, v in op.init_records.items()})

    def _op_PodRead(self, op, env):
        pod, record = self._get(env, op.pod_ref), _name(op.record_name)
        if isinstance(pod, Ref):
            m = re.fullmatch(r"idx_(\d+)", record)
            self._set(env, op.result, Ref(pod.path + ((int(m.group(1)),) if m else (record,))))
        elif isinstance(pod, dict):
            self._set(env, op.result, pod.get(record, Unknown()))
        else:
            self._set(env, op.result, Unknown(_signals(pod)))

    def _op_PodWrite(self, op, env):
        pod = self._get(env, op.pod_ref)
        if isinstance(pod, dict):
            pod[_name(op.record_name)] = self._get(env, op.value)

    # ── Constraints and calls ──

    def _op_ConstrainEq(self, op, env):
        lhs, rhs = self._get(env, op.lhs), self._get(env, op.rhs)
        dims = next((_dims(str(t)) for t in op.types if _dims(str(t))), ())
        if dims:
            # One constraint per element
            for flat in range(_product(dims)):
                idx, rest = [], flat
                for d in reversed(dims):
                    idx.append(rest % d)
                    rest //= d
                idx = tuple(reversed(idx))
                self._emit(_element(lhs, idx), _element(rhs, idx))
        else:
            self._emit(lhs, rhs)

    def _emit(self, lhs, rhs):
        self.constraints.append((self.stack[-1], _signals(lhs) | _signals(rhs)))

    def _op_ConstrainIn(self, op, env):
        raise LLZKStructureError("constrain.in has no r1cs counterpart")

    def _op_FunctionCall(self, op, env):
        callee = str(op.callee).lstrip("@").replace("::@", "::")
        args = [self._get(env, a) for a in op.args]
        if callee.endswith("::constrain"):
            comp = args[0]
            if not isinstance(comp, Ref):
                raise LLZKStructureError(f"constrain call on a non-storage value: {op!r}")
            struct = callee[:-len("::constrain")]
            self._enter_instance(comp.path, struct, self.stack[-1])
            self.stack.append(comp.path)
            self._call(self.functions[callee], args)
            self.stack.pop()
            results = []
        elif callee.endswith("::compute"):
            raise LLZKStructureError(f"compute call inside a constrain function: {op!r}")
        elif all(_is_concrete(a) for a in args):
            results = self._call(self.functions[callee], args)
        else:
            # A circom function emits no constraints: with arguments depending
            # on signals only what its results depend on matters
            signals = frozenset().union(*(_signals(a) for a in args))
            results = [Unknown(signals)] * len(_result_names(op.results))
        self._set_results(env, op.results, results)

    def _op_FunctionReturn(self, op, env):
        raise Return([self._get(env, v) for v in op.operands])

    # ── Control flow ──

    def _op_SCFYield(self, op, env):
        return [self._get(env, v) for v in op.operands]

    def _op_SCFCondition(self, op, env):
        return [self._get(env, op.condition)] + [self._get(env, v) for v in op.args]

    def _op_SCFIf(self, op, env):
        cond = self._get(env, op.condition)
        if isinstance(cond, int):
            values = self._block(op.then_body if cond else op.else_body, env) or []
        else:
            # Constraints cannot depend on signals: neither branch may emit any
            for branch in (op.then_body, op.else_body):
                if _emits(branch):
                    raise LLZKStructureError(f"constraints under a condition on signals: {op!r}")
            values = [Unknown(_signals(cond))] * len(_result_names(op.results))
        self._set_results(env, op.results, values)

    def _op_SCFExecuteRegion(self, op, env):
        self._set_results(env, op.results, self._block(op.body, env) or [])

    def _op_SCFFor(self, op, env):
        lb, ub, step = (self._get(env, v) for v in (op.lb, op.ub, op.step))
        values = [self._get(env, init) for _, init in op.iter_args]
        i = lb
        while i < ub:
            self._set(env, op.iv, i)
            for (arg, _), v in zip(op.iter_args, values):
                self._set(env, arg, v)
            values = self._block(op.body, env) or []
            i += step
        self._set_results(env, op.results, values)

    def _op_SCFWhile(self, op, env):
        values = [self._get(env, init) for _, init in op.init_args]
        while True:
            for (arg, _), v in zip(op.init_args, values):
                self._set(env, arg, v)
            cond, *values = self._block(op.before_body, env)
            if not isinstance(cond, int):
                raise LLZKStructureError(f"loop condition depends on a signal: {op!r}")
            if not cond:
                break
            for (arg, _), v in zip(op.after_args, values):
                self._set(env, arg, v)
            values = self._block(op.after_body, env) or []
        self._set_results(env, op.results, values)


def _signature_args(function) -> List[Tuple[str, str]]:
    """[(SSA name, function.arg_name or the SSA name)] of the arguments, in order."""
    names = function.in_arg_names
    return [(arg, names.get(arg, arg)) for arg, _ in function.in_args]


def _result_names(results) -> List[str]:
    """SSA names of the results: `%1:2` is `%1#0` and `%1#1`."""
    flat = []
    for r in results:
        n = getattr(r, "n_components", 1)
        flat.extend([r.name] if n == 1 else [f"{r.name}#{i}" for i in range(n)])
    return flat


def _is_concrete(value) -> bool:
    if isinstance(value, int):
        return True
    if isinstance(value, Array):
        return all(_is_concrete(v) for v in value.data.values())
    if isinstance(value, dict):
        return all(_is_concrete(v) for v in value.values())
    return False


def _product(dims):
    n = 1
    for d in dims:
        n *= d
    return n


def _element(value, idx):
    if isinstance(value, Ref):
        return Ref(value.path + idx)
    if isinstance(value, Array):
        return value.read(idx)
    return value


def _emits(ops) -> bool:
    for op in ops:
        kind = type(op).__name__
        if kind == "ConstrainEq" or (kind == "FunctionCall" and str(op.callee).endswith("@constrain")):
            return True
        for attr in ("body", "then_body", "else_body", "before_body", "after_body"):
            if _emits(getattr(op, attr, None) or []):
                return True
    return False


# ── Layout: wire -> (instance, signal) ──────────────────────────────────────

_SEGMENT = re.compile(r'\["((?:[^"\\]|\\.)*)"\]|\[(\d+)\]')


def parse_layout_paths(path):
    """{wire: (circom-style path, came through an `x$inputs` pod or an argument of main)}"""
    signals, wires = {}, {}
    with open(path) as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("signal "):
                signal_id, raw = line[len("signal "):].split("\t")
                signals[int(signal_id)] = raw
            elif line.startswith("wire "):
                wire, target = line[len("wire "):].split("\t")
                if target != "<one>":
                    wires[int(wire)] = _layout_path(signals[int(target.split()[1])])
    return wires


def _layout_path(raw):
    root = "arg" if raw.startswith("arg") else "main"
    segments, is_input = [], root == "arg"
    for name, index in _SEGMENT.findall(raw[len(root):]):
        if index:
            segments.append(int(index))
        elif name.endswith("$inputs"):
            segments.append(name[:-len("$inputs")])
            is_input = True
        elif re.fullmatch(r"idx_\d+", name):
            segments.append(int(name[len("idx_"):]))
        else:
            segments.append(name)
    return tuple(segments), is_input


# ── The structure ───────────────────────────────────────────────────────────

def _component_name(path, parent):
    out = ""
    for seg in path[len(parent):]:
        out += f"[{seg}]" if isinstance(seg, int) else (f".{seg}" if out else seg)
    return out


def _owner(path, instances):
    for n in range(len(path) - 1, -1, -1):
        if path[:n] in instances:
            return path[:n]
    raise LLZKStructureError(f"signal {path} belongs to no component")


def build_structure(llzk_path, r1cs_path, layout_path, prime_name="goldilocks"):
    with open(llzk_path) as f:
        module = init_llzk_parser(f.readlines()).parse()[0]
    interp = ConstrainInterpreter(module, FIELD_PRIMES[prime_name])
    interp.run()

    _, constraints = parse_r1cs(r1cs_path)
    if len(constraints) != len(interp.constraints):
        raise LLZKStructureError(
            f"{r1cs_path} has {len(constraints)} constraints but the constrain "
            f"functions of {llzk_path} emit {len(interp.constraints)}")

    wires = parse_layout_paths(layout_path)
    for i, ((_, emitted), constraint) in enumerate(zip(interp.constraints, constraints)):
        in_r1cs = {wires[w][0] for lc in constraint for w in lc if w != 0}
        if not in_r1cs <= emitted:
            raise LLZKStructureError(
                f"constraint {i} of the r1cs uses {sorted(in_r1cs - emitted)}, "
                f"which the constraint emitted at that position does not")

    instances = interp.instances
    order = []  # preorder, as circom numbers its nodes

    def visit(path):
        order.append(path)
        for child in instances[path].children:
            visit(child)
    visit(())
    node_id = {path: i for i, path in enumerate(order)}

    # Signals of each instance: outputs, inputs, intermediates; each in
    # declaration order and its elements in index order.
    by_instance = {path: [] for path in order}
    for wire, (path, is_input) in wires.items():
        owner = _owner(path, instances)
        name, idx = path[len(owner)], path[len(owner) + 1:]
        struct = interp.structs[instances[owner].struct]
        if is_input:
            names = interp._arg_names(interp.functions[instances[owner].struct + "::constrain"])
            category, position = 1, names.index(name)
        else:
            members = [m for m in struct.body if type(m).__name__ == "StructMember"]
            position = next(i for i, m in enumerate(members) if _name(m.sym_name) == name)
            category = 0 if members[position].is_out else 2
        by_instance[owner].append(((category, position, idx), wire, category))

    constraints_of = {path: [] for path in order}
    for i, (path, _) in enumerate(interp.constraints):
        constraints_of[path].append(i)

    nodes, classes = [], {}
    for path in order:
        inst = instances[path]
        signals = sorted(by_instance[path])
        nodes.append({
            "node_name": inst.struct.split("::")[-1],
            "component_name": "" if inst.parent is None else _component_name(path, inst.parent),
            "node_id": node_id[path],
            "constraints": constraints_of[path],
            "input_signals": [w for _, w, c in signals if c == 1],
            "output_signals": [w for _, w, c in signals if c == 0],
            "signals": [w for _, w, _ in signals],
            "is_custom": False,
            "is_deterministic": False,
            "successors": [node_id[c] for c in inst.children],
            "predecessors": [] if inst.parent is None else [node_id[inst.parent]],
        })
        classes.setdefault(inst.struct, []).append(node_id[path])

    equivalency = list(classes.values())
    return {
        "timing": {"graph_construction": 0.0, "clustering": 0.0, "dag_construction": 0.0,
                   "equivalency": 0.0, "total": 0.0},
        "nodes": nodes,
        "equivalency_local": equivalency,
        "equivalency_structural": equivalency,
    }


def llzk_to_structure(llzk_path, r1cs_path, layout_path, structure_path, prime_name="goldilocks"):
    structure = build_structure(llzk_path, r1cs_path, layout_path, prime_name)
    with open(structure_path, "w") as f:
        json.dump(structure, f, indent=2)
    return structure


if __name__ == "__main__":
    if len(sys.argv) not in (5, 6):
        sys.exit(f"usage: {sys.argv[0]} <file.llzk> <file.r1cs> <file.llzk-layout> <out_structure.json> [prime]")
    llzk_to_structure(*sys.argv[1:])
